  [("autoridad", "persona que aplica las reglas del juego, como un árbitro o un profesor"), ("reparar", "hacer algo para arreglar un error"), ("disculpa", "reconocer que me equivoqué y lamentarlo"), ("consecuencia", "lo que ocurre después de romper una regla"), ("reanudar", "continuar el juego después de una pausa")],
  [("Respetar la decisión", "La autoridad dice que la pelota salió, pero tú crees que no. ¿Gritas o esperas a que termine la jugada y lo comentas con calma?", ["Respeto la decisión.", "Puedo expresar mi opinión con calma.", "Espero y lo comento con calma."], "Esperas y lo comentas con calma"),
   ("Reparar", "Chocaste sin querer con un compañero y se cayó. ¿Qué haces primero: ver si está bien y pedir disculpas, o seguir jugando?", ["Primero la persona.", "Veo si está bien.", "Veo cómo está y pido disculpas."], "Ver si está bien y pedir disculpas")],
